players.script:
# rushdown.pf — relentless pressure.
# Strategy: walk in fast and keep attacking. Kick from max range, follow up
# with a punch, and mix in a sweep against blockers.
loop {
  if in_range(kick) {
    kick
    if enemy.blocking { sweep } else { punch }
  } else {
    move_forward x4
  }
}

# turtle.pf — patient defender.
# Strategy: block while the enemy attacks and kick back as soon as it is in
# kick range and not attacking. Blocking forever is not safe: the 4th block
# in a row breaks the guard, so after 3 blocks it backs off instead. A
# blocked kick is answered with a throw, since a throw beats a block.
loop {
  if enemy.attacking {
    if guard >= 3 { move_back x3 } else { high_block hold 6 }
  } elif in_range(kick) {
    kick
  } else {
    high_block hold 8
  }
}
on_block { throw }
on_hit { move_back x3 }
